import sys, json, os, time
import numpy as np
from PIL import Image
from rcb_client import Robot

OUT='/app/output'
os.makedirs(OUT,exist_ok=True)
r=Robot()
spec=r.spec()
with open(f'{OUT}/spec.json','w') as f: json.dump(spec,f,indent=2)
print('READY',json.dumps({'control_dt':spec.get('control_dt'),'cameras':list(spec.get('cameras',{})),'action':spec.get('action_types',{}).get('joint_position'),'proprio_layout':spec.get('proprio_layout')}),flush=True)
seq=0
while True:
    line=sys.stdin.readline()
    if not line: break
    try:
        cmd=json.loads(line)
        if cmd.get('op')=='obs':
            res=r.get_obs(cameras=cmd.get('cameras'),seconds=cmd.get('seconds',0),include_depth=cmd.get('depth',False),video=cmd.get('video','none'))
        elif cmd.get('op')=='submit':
            res=r.submit('joint_position',np.array(cmd['actions'],dtype=np.float64),cameras=cmd.get('cameras'),video=cmd.get('video','none'),include_depth=cmd.get('depth',False),note=cmd.get('note',''))
        elif cmd.get('op')=='status':
            print('STATUS',json.dumps(r.status()),flush=True); continue
        elif cmd.get('op')=='quit': break
        else: print('ERROR unknown op',flush=True); continue
        seq+=1
        for cam,arr in res.last.items(): Image.fromarray(arr).save(f'{OUT}/{seq:03d}_{cam}.png')
        for cam,arr in res.depth.items(): np.save(f'{OUT}/{seq:03d}_{cam}_depth.npy',arr)
        if res.frames:
            for cam,fs in res.frames.items():
                for i,frame in enumerate(fs): Image.fromarray(frame).save(f'{OUT}/{seq:03d}_{cam}_{i:03d}.png')
        if res.video:
            for cam,buf in res.video.items(): open(f'{OUT}/{seq:03d}_{cam}.mp4','wb').write(buf)
        with open(f'{OUT}/{seq:03d}_meta.json','w') as f: json.dump(res.meta,f,indent=2)
        print('RESULT',seq,json.dumps({'meta':res.meta,'last':list(res.last),'depth':{k:list(v.shape) for k,v in res.depth.items()},'frames':{k:list(v.shape) for k,v in res.frames.items()}}),flush=True)
    except Exception as e:
        print('ERROR',repr(e),flush=True)
PY
